  <section class="uk-card uk-card-default uk-card-small uk-card-body kontor-card pw-table-panel uk-overflow-auto kontor-tablewrap"><header class="kontor-sectionhead"><div><p class="kontor-eyebrow">Authentication</p><h3>API tokens</h3></div></header><form class="uk-form-stacked kontor-nativeform" method="post" action="<?= $e($adminUrl) ?>api-token/"><input type="hidden" name="<?= $e($csrfName) ?>" value="<?= $e($csrfValue) ?>"><label class="kontor-nativefield"><span>Name *</span><input name="name" required></label><label class="kontor-nativefield kontor-nativefield--wide"><span>Scopes</span><input name="scopes" placeholder="organizations:read, organizations:write"></label><label class="kontor-nativefield"><span>Expires</span><input name="expires_at" type="datetime-local"></label><div class="kontor-nativeform__actions"><button class="uk-button uk-button-primary kontor-button" type="submit">Issue token</button></div></form><?php if ($tokens !== []): ?><table class="uk-table uk-table-divider uk-table-hover uk-table-middle uk-table-small kontor-table"><thead><tr><th>Name</th><th>Scopes</th><th>Status</th><th>Last used</th><th></th></tr></thead><tbody><?php foreach ($tokens as $token): ?><tr><td><strong><?= $e($token->name) ?></strong></td><td><?= $e($token->scopes === [] ? 'unrestricted' : implode(', ', $token->scopes)) ?></td><td><span class="uk-label kontor-pill<?= $token->isActive() ? '' : ' kontor-pill--inactive' ?>"><?= $e($token->status) ?></span></td><td><?= $e($token->lastUsedAt?->format('Y-m-d H:i') ?? 'never') ?></td><td><?php if ($token->isActive()): ?><form method="post" action="<?= $e($adminUrl) ?>api-token-revoke/"><input type="hidden" name="<?= $e($csrfName) ?>" value="<?= $e($csrfValue) ?>"><input type="hidden" name="token_uid" value="<?= $e($token->uid->toString()) ?>"><button class="uk-button uk-button-secondary kontor-button kontor-button--ghost" type="submit">Revoke</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php else: ?><div class="pw-empty-state uk-placeholder uk-text-center kontor-empty"><p>No API tokens issued.</p></div><?php endif; ?></section>
  <section class="uk-card uk-card-default uk-card-small uk-card-body kontor-card pw-table-panel uk-overflow-auto kontor-tablewrap"><header class="kontor-sectionhead"><div><p class="kontor-eyebrow">OpenAPI 3.0</p><h3>Registered resources</h3></div></header><?php if ($resources !== []): ?><table class="uk-table uk-table-divider uk-table-hover uk-table-middle uk-table-small kontor-table"><thead><tr><th>Resource</th><th>Fields</th><th>Operations</th></tr></thead><tbody><?php foreach ($resources as $resource): ?><?php $schema = $resource->schema(); ?><tr><td><strong><code>/<?= $e($resource->key()) ?></code></strong></td><td><?= $e(implode(', ', array_keys($schema->fields))) ?></td><td>list, find<?= $schema->supportsCreate ? ', create' : '' ?><?= $schema->supportsUpdate ? ', update' : '' ?><?= $schema->supportsDelete ? ', delete' : '' ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?><details><summary>OpenAPI document</summary><pre><code><?= $e(json_encode($openApi, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) ?></code></pre></details></section>
