><?php endif; ?>
  <section class="uk-card uk-card-default uk-card-small uk-card-body kontor-card pw-table-panel uk-overflow-auto kontor-tablewrap"><header class="kontor-sectionhead"><div><p class="kontor-eyebrow">Observability</p><h3>Recent webhook deliveries</h3></div></header><?php if ($deliveries !== []): ?><table class="uk-table uk-table-divider uk-table-hover uk-table-middle uk-table-small kontor-table"><thead><tr><th>When</th><th>Event</th><th>Status</th><th>Attempts</th><th>Response</th></tr></thead><tbody><?php foreach ($deliveries as $delivery): ?><tr><td><?= $e($delivery->createdAt->format('Y-m-d H:i:s')) ?></td><td><?= $e($delivery->eventName) ?></td><td><?= $e($delivery->status) ?></td><td><?= $e((string) $delivery->attemptCount) ?></td><td><?= $e($delivery->responseCode !== null ? (string) $delivery->responseCode : ($delivery->lastError ?? '—')) ?></td></tr><?php endforeach; ?></tbody></table><?php else: ?><div class="pw-empty-state uk-placeholder uk-text-center kontor-empty"><p>No webhook deliveries yet.</p></div><?php endif; ?></section>
